#include "MatchThreeGame.h"
#include <algorithm>
namespace NeoEngine { MatchThreeGame::MatchThreeGame():m_Board{1,1,2,3,4,2,3,1,4,5,3,1,2,4,5,4,5,4,3,2,5,4,5,2,1}{} bool MatchThreeGame::HasMatch()const{for(uint8_t r=0;r<5;++r)for(uint8_t c=0;c<3;++c){auto v=m_Board[r*5+c];if(v&&v==m_Board[r*5+c+1]&&v==m_Board[r*5+c+2])return true;}for(uint8_t c=0;c<5;++c)for(uint8_t r=0;r<3;++r){auto v=m_Board[r*5+c];if(v&&v==m_Board[(r+1)*5+c]&&v==m_Board[(r+2)*5+c])return true;}return false;} bool MatchThreeGame::Swap(uint8_t r1,uint8_t c1,uint8_t r2,uint8_t c2){if(!Valid(r1,c1)||!Valid(r2,c2)){m_Error=MatchThreeError::InvalidCoordinate;return false;}if((r1==r2?c1-c2:c2-c1)+(c1==c2?r1-r2:r2-r1)!=1 && !(r1==r2&&((c1>c2?c1-c2:c2-c1)==1)) && !(c1==c2&&((r1>r2?r1-r2:r2-r1)==1))){m_Error=MatchThreeError::NotAdjacent;return false;}auto a=r1*5+c1,b=r2*5+c2;std::swap(m_Board[a],m_Board[b]);if(!HasMatch()){std::swap(m_Board[a],m_Board[b]);m_Error=MatchThreeError::NoMatch;return false;}m_Error=MatchThreeError::None;return true;} uint32_t MatchThreeGame::Resolve(){std::array<bool,25> remove{};for(uint8_t r=0;r<5;++r)for(uint8_t c=0;c<3;++c){auto v=m_Board[r*5+c];if(v&&v==m_Board[r*5+c+1]&&v==m_Board[r*5+c+2])remove[r*5+c]=remove[r*5+c+1]=remove[r*5+c+2]=true;}for(uint8_t c=0;c<5;++c)for(uint8_t r=0;r<3;++r){auto v=m_Board[r*5+c];if(v&&v==m_Board[(r+1)*5+c]&&v==m_Board[(r+2)*5+c])remove[r*5+c]=remove[(r+1)*5+c]=remove[(r+2)*5+c]=true;}uint32_t count=0;for(size_t i=0;i<25;++i)if(remove[i]){m_Board[i]=static_cast<uint8_t>(((i+m_Turn)%5)+1);++count;}if(count){m_Score+=count*10;++m_Turn;}return count;} uint64_t MatchThreeGame::DeterministicState()const{uint64_t h=1469598103934665603ULL;for(auto v:m_Board){h^=v;h*=1099511628211ULL;}h^=m_Score;h*=1099511628211ULL;h^=m_Turn;return h;} }
